"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Demo: the trained system end to end on the sample scenes in data/samples/. For every decision point it prints the
stop and respond probabilities and decisions of ours (the step 2d read-out) and of the same model's original read-out,
next to the right answers.

Steps per scene (each one calls the project's own code in src/):
  1. audio: the 8 s window that ends at each decision point (what the decision model hears) and, for the two
     episodes, the whole scene;
  2. front end (p1v4_feats.py, p1v4_sed.py): Whisper-small transcripts of the speech segments, speaker tags (user / not
     the user) from ECAPA-TDNN embeddings compared with the user's enrolment (models/speaker_enrolment.json), and the
     fine-tuned sound-event detector;
  3. situation text (p1v4_situation.py);
  4. the fine-tuned VoxTurn (p1v4_l1.py, p1v4_readout.py) reads the window and the text; its option head gives the
     original read-out's probabilities, and the step 2d read-out (p1v4_readout_2d.py) reads its last-layer states plus
     the audio encoder's per-second outputs;
  5. decisions at the frozen thresholds in models/settings.json (p1v4_score.py decide).

Front end (--front-end):
  live    (default) recomputed from the audio. Episodes ship their whole audio, so everything is recomputed as when
          the training set was processed (the detector runs on the audio from the scene start to the decision point).
          The other scenes ship only their 8 s windows: the speech inside the window is transcribed and tagged and the
          detector runs on the window; the user's opening request, which ends before the window starts, keeps the
          transcript and tag stored with the scene.
  stored  the front-end outputs stored with the scene (computed when the training set was processed), so every input
          is exactly the training input; the rebuilt situation text is checked against the stored one.

usage (repo root, GPU environment):
  python -X utf8 src/demo.py [--scene ID ...] [--front-end live|stored] [--show-text] [--out results.json]
Paths (defaults): --samples data/samples, --weights models, --detector models/release/sed.pt, --models-dl data/models_dl
(voxturn_fe3d4a3, spkrec-ecapa-voxceleb_0f99f2d and panns_d2f4b8c; see SETUP.md). Needs an NVIDIA GPU with CUDA.
"""
import argparse
import hashlib
import json
import os
import sys
import time

import numpy as np
import soundfile as sf

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402
import p1v4_feats as F  # noqa: E402
import p1v4_score as S  # noqa: E402
import p1v4_situation as SIT  # noqa: E402

SR = F.SR
WIN = int(D.WIN_S * SR)
QNAME = {"S": "stop", "R": "respond"}
SAY = {"stop": "stop", "continue": "continue", "respond": "respond", "not": "don't respond", None: "(not scored)"}


def need(path, hint):
    if not os.path.exists(path):
        raise SystemExit(f"{path} not found: {hint} (see SETUP.md)")
    return path


def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for block in iter(lambda: f.read(1 << 20), b""):
            h.update(block)
    return h.hexdigest()


def check_settings(args):
    """models/settings.json: the frozen thresholds, the file hashes, and the front-end settings, which must equal the
    constants the code uses."""
    import p1v4_l1 as L1
    st = json.load(open(need(os.path.join(args.weights, "settings.json"), "the models/ folder is incomplete"),
                        encoding="utf-8"))
    code = {"transcripts.revision": (st["transcripts"]["revision"], F.WHISPER[1]),
            "detector.frame_threshold": (st["detector"]["frame_threshold"], F.SOUND_THR),
            "detector.merge_gap_s": (st["detector"]["merge_gap_s"], F.MERGE_GAP_S),
            "detector.classes": (st["detector"]["classes"], D.DET_CLASSES),
            "decision_model.max_text_tokens": (st["decision_model"]["max_text_tokens"], L1.MAX_TEXT_TOKENS)}
    bad = [k for k, (a, b) in code.items() if a != b]
    if bad:
        raise SystemExit(f"models/settings.json differs from the code: {bad}")
    files = {"l1_new.pt": os.path.join(args.weights, "l1_new.pt"),
             "readouts_2d.npz": os.path.join(args.weights, "readouts_2d.npz"),
             "release/sed.pt": args.detector}
    for name, path in files.items():
        need(path, "download the detector from the GitHub Release (models/release/README.md)" if name == "release/sed.pt"
             else "the models/ folder is incomplete")
        if sha256(path) != st["files"][name]["sha256"]:
            raise SystemExit(f"{path}: sha256 differs from models/settings.json (incomplete download?)")
    return st


# ------------------------------------------------------------------------------------------------ scenes

def load_scenes(root, wanted):
    man = json.load(open(need(os.path.join(root, "manifest.json"), "the sample scenes are missing"), encoding="utf-8"))
    scenes = [json.load(open(os.path.join(root, e["scene_json"]), encoding="utf-8")) for e in man["scenes"]
              if not wanted or e["scene_id"] in wanted]
    missing = set(wanted or []) - {s["scene_id"] for s in scenes}
    if missing:
        raise SystemExit(f"unknown scene(s) {sorted(missing)}; available: {[e['scene_id'] for e in man['scenes']]}")
    return scenes


def meta_row(scene, ver):
    """One version of a sample scene in the meta-row format the project's code reads (p1v4_data.py): sources with
    times, decision points and the assistant's turns."""
    src = [{"id": s["id"], "kind": "speech", "who": s["who"], "text": s["text"], "start": s["start"], "end": s["end"]}
           for s in ver["speech"]]
    for s in ver["sounds"]:
        if s["class"] == "tv_recording":               # a real TV recording is transcribed like speech
            src.append({"id": s["id"], "kind": "tvfile", "start": s["start"], "end": s["end"]})
        else:
            src.append({"id": s["id"], "kind": "clip", "cls": s["class"], "start": s["start"], "end": s["end"]})
    pts = []
    for i, p in enumerate(ver["points"]):
        assert p["k"] == i, (p["id"], i)
        kind = "RS" if set(p["asks"]) == {"stop", "respond"} else ("S" if p["asks"] == ["stop"] else "R")
        pts.append({"k": p["k"], "t": p["t"], "kind": kind, "line": p["line"],
                    "assistant_speaking": p["assistant_speaking"],
                    "gold": {"S": p["gold"]["stop"], "R": p["gold"]["respond"]}})
    return {"unit": scene["scene_id"], "version": ver["version"], "part": scene["part"], "sources": src,
            "points": pts, "assistant": ver["assistant"]}


def stored_front(p):
    fe = p["front_end"]
    return (dict(fe["transcripts"]), dict(fe["speaker_tag"]),
            [(d["class"], d["start"], d["end"], d["peak"]) for d in fe["detected_sounds"]])


# ------------------------------------------------------------------------------------------------ front end

def load_detector(models_dl, ckpt):
    """p1v4_sed.build_model + p1v4_sed.load, without loading the AudioSet checkpoint first: sed.pt holds every weight
    of the fine-tuned network, so the 331 MB AudioSet file is needed only to train the detector, not to run it."""
    import torch
    import torch.nn as nn
    import p1v4_sed as SED
    SED.PANNS_DIR = os.path.abspath(os.path.join(models_dl, "panns_d2f4b8c"))
    need(os.path.join(SED.PANNS_DIR, "models.py"), "download the PANNs code")
    sys.path.insert(0, SED.PANNS_DIR)
    from models import AttBlock, Cnn14_DecisionLevelAtt
    m = Cnn14_DecisionLevelAtt(sample_rate=32000, window_size=1024, hop_size=320, mel_bins=64, fmin=50, fmax=14000,
                               classes_num=527)
    m.att_block = AttBlock(2048, len(D.DET_CLASSES), activation="sigmoid")
    m.spec_augmenter = nn.Identity()
    m.load_state_dict(torch.load(ckpt, map_location="cpu", weights_only=True))
    return m.cuda().eval()


class FrontEnd:
    """Whisper-small, ECAPA-TDNN against the user's enrolment, and the detector, applied as p1v4_feats.run does."""

    def __init__(self, args, settings):
        F.ECAPA_SRC = need(os.path.join(args.models_dl, "spkrec-ecapa-voxceleb_0f99f2d"), "download ECAPA-TDNN")
        self.whisper = F.Whisper(*F.WHISPER)
        self.ecapa = F.load_ecapa()                    # speechbrain copies its files to data/models_dl/spkrec-ecapa-voxceleb
        self.det = load_detector(args.models_dl, args.detector)
        en = json.load(open(os.path.join(args.weights, "speaker_enrolment.json"), encoding="utf-8"))["embeddings"]
        self.enrol = {k: np.asarray(v, np.float32) / (np.linalg.norm(v) + 1e-9) for k, v in en.items()}
        self.threshold = settings["speaker_id"]["threshold"]

    def sounds(self, x):
        """Detector runs over int16 audio x (p1v4_feats.run: the prefix up to the decision point)."""
        import torch
        import p1v4_sed as SED
        xx = torch.from_numpy(SED.to32(x.astype(np.float32) / 32768.0))[None].cuda()
        with torch.no_grad(), torch.autocast("cuda", dtype=torch.bfloat16):
            f, _, _ = SED.forward(self.det, xx)
        n_keep = int(np.floor(len(x) / SR * 100)) + 1
        return F.sound_segments(f[0, :n_keep].float().cpu().numpy())

    def speech(self, cuts):
        """{sha1: int16 cut} -> {sha1: (transcript, 192-d embedding)}, batched as p1v4_feats.run (flush)."""
        import torch
        keys = sorted(cuts, key=lambda k: len(cuts[k]))
        out = {}
        for i in range(0, len(keys), 32):
            ks = keys[i:i + 32]
            xs = [cuts[k].astype(np.float32) / 32768.0 for k in ks]
            texts = self.whisper(xs)
            n = max(len(x) for x in xs)
            wav = np.zeros((len(xs), n), np.float32)
            for j, x in enumerate(xs):
                wav[j, :len(x)] = x
            lens = torch.tensor([len(x) / n for x in xs], dtype=torch.float32)
            with torch.no_grad():
                e = self.ecapa.encode_batch(torch.from_numpy(wav).cuda(), lens.cuda()).squeeze(1).float().cpu().numpy()
            for k, tr, v in zip(ks, texts, e):
                out[k] = (tr, v.astype(np.float16).astype(np.float32))   # stored as float16 in training
        return out

    def run(self, scene, ver, row, root, stored):
        """{k: (transcripts, tags, sounds, scores)} for one version, and the number of speech segments that keep their
        stored outputs because they start before the audio this sample ships."""
        user = "kokoro:" + scene["voices"]["user"]
        if user not in self.enrol:
            raise SystemExit(f"no enrolment for the user voice {user} in models/speaker_enrolment.json")
        whole = sf.read(os.path.join(root, ver["audio"]), dtype="int16")[0] if ver["audio"] else None
        per_point, cuts, kept = {}, {}, 0
        for p in ver["points"]:
            k, e = p["k"], int(round(p["t"] * SR))
            w = sf.read(os.path.join(root, p["window"]), dtype="int16")[0]
            if whole is not None:                       # the episode's window must be its slice of the whole scene
                assert np.abs(whole[e - WIN:e].astype(np.int32) - w.astype(np.int32)).max() <= 1, p["id"]
                x, a0 = whole[:e], 0
            else:
                x, a0 = np.concatenate([np.zeros(e - WIN, np.int16), w]), e - WIN
            one = dict(row, points=[r for r in row["points"] if r["k"] == k])
            segs = {}
            for _, key, cut in F.segment_cuts(one, x):
                start = next(s["start"] for s in row["sources"] if s["id"] == key.split("@")[0])
                if int(round(start * SR)) >= a0:
                    h = hashlib.sha1(cut.tobytes()).hexdigest()
                    segs[key] = h
                    cuts[h] = cut
                else:
                    segs[key] = None
                    kept += 1
            snd = [(c, round(s0 + a0 / SR, 2), round(s1 + a0 / SR, 2), pk) for c, s0, s1, pk in self.sounds(x[a0:])]
            if a0:                                      # a window alone: earlier sounds keep their stored runs
                snd = sorted([s for s in stored[k][2] if s[2] <= a0 / SR] + snd, key=lambda s: (s[1], s[0]))
            per_point[k] = (segs, snd)
        heard = self.speech(cuts)
        out = {}
        for k, (segs, snd) in per_point.items():
            tr, tags, scores = {}, {}, {}
            for key, h in segs.items():
                if h is None:
                    tr[key], tags[key], scores[key] = stored[k][0][key], stored[k][1][key], None
                    continue
                text, emb = heard[h]
                scores[key] = float(emb / (np.linalg.norm(emb) + 1e-9) @ self.enrol[user])
                tr[key], tags[key] = text, ("user" if scores[key] >= self.threshold else "other")
            out[k] = (tr, tags, snd, scores)
        return out, kept


# ------------------------------------------------------------------------------------------------ decision model

class Decider:
    """The fine-tuned VoxTurn (VoxTurn + our LoRA adapter and option head) and the step 2d read-out."""

    def __init__(self, args):
        import torch
        import l1_voxturn
        import p1v4_l1 as L1
        import p1v4_readout_2d as R2D
        vdir = need(os.path.join(args.models_dl, "voxturn_fe3d4a3"), "download VoxTurn")
        mod, vt = l1_voxturn.load_official(vdir)
        self.model = L1.L1v4(mod, vt)                   # as p1v4_l1.build(), with the VoxTurn folder given explicitly
        vt.llm.eval()
        L1.load_new_state(self.model, torch.load(os.path.join(args.weights, "l1_new.pt"), weights_only=True))
        self.model.eval()
        R2D.OUT = args.weights                          # p1v4_readout_2d.load_2d reads <OUT>/readouts_2d.npz
        self.ro = R2D.load_2d()

    def score(self, items, batch):
        """items: [{"id", "wave", "text", "marker", "qs"}] -> (ours, original), each {(scene, version, k): {"S", "R"}};
        features kept in float16 before the read-out, as the final evaluation (p1v4_final.readout_features) did."""
        import torch
        import p1v4_readout as RO
        import p1v4_readout_2d as R2D
        H, QW, QT, PO, SM, SX = [], [], [], [], [], []
        for i in range(0, len(items), batch):
            chunk = items[i:i + batch]
            waves = torch.stack([torch.from_numpy(it["wave"]) for it in chunk]).cuda()
            h, _, qw, po = RO.forward_states(self.model, waves, [it["text"] for it in chunk],
                                             [it["marker"] for it in chunk],
                                             [[RO.TASK[q] for q in it["qs"]] for it in chunk])
            sm, sx, _ = R2D.per_second(self.model.vt, waves)
            H.append(h.astype(np.float16))
            SM.append(sm.astype(np.float16))
            SX.append(sx.astype(np.float16))
            QW.append(qw + i)
            QT += [q for it in chunk for q in it["qs"]]
            PO.append(po)
        ids = np.array([it["id"] for it in items])
        z = {"states": np.concatenate(H), "q_win": np.concatenate(QW), "q_task": np.array(QT), "ids": ids,
             "p_old": np.concatenate(PO)}
        ours = R2D.scores_2d(z, R2D.Sec(None, ids, np.concatenate(SM), np.concatenate(SX)), self.ro)
        return ours, RO.scores_of(z, None, None)


# ------------------------------------------------------------------------------------------------ output

def heard_line(row, k, tr, tags, snd):
    """What the front end perceived at point k: the line just said and the sounds detected in the 8 s window."""
    p = row["points"][k]
    if p["line"]:
        who = "user" if tags.get(p["line"]) == "user" else "not the user"
        said = f'just said ({who}): "{tr.get(p["line"], "")}"'
    else:
        said = "nobody just spoke"
    w0 = p["t"] - D.WIN_S
    inside = [f"{SIT.SOUND_NAMES.get(c, c)} {s0:.1f}-{min(s1, p['t']):.1f} s ({pk:.2f})"
              for c, s0, s1, pk in snd if s1 > w0]
    return said + " | sounds reaching into the window: " + ("; ".join(inside) if inside else "none")


def main():
    ap = argparse.ArgumentParser(description="Run the trained system on the sample scenes (see the module docstring).")
    ap.add_argument("--samples", default="data/samples", help="folder with manifest.json (default data/samples)")
    ap.add_argument("--scene", nargs="*", help="scene ids to run (default: all)")
    ap.add_argument("--front-end", choices=("live", "stored"), default="live")
    ap.add_argument("--weights", default="models", help="folder with l1_new.pt, readouts_2d.npz, settings.json")
    ap.add_argument("--detector", default="models/release/sed.pt", help="fine-tuned detector (GitHub Release)")
    ap.add_argument("--models-dl", default="data/models_dl", help="downloaded base models (see SETUP.md)")
    ap.add_argument("--batch", type=int, default=8, help="decision windows per forward pass (default 8)")
    ap.add_argument("--show-text", action="store_true", help="print the situation text of every point")
    ap.add_argument("--out", help="write every probability, decision and input text to this JSON file")
    args = ap.parse_args()

    import logging
    import warnings
    import torch
    import transformers
    logging.getLogger("torch.utils.flop_counter").setLevel(logging.ERROR)       # library notices, not results
    transformers.logging.set_verbosity_error()
    transformers.utils.logging.disable_progress_bar()
    warnings.filterwarnings("ignore", category=FutureWarning)
    warnings.filterwarnings("ignore", message="Module 'speechbrain.pretrained' was deprecated")
    if not torch.cuda.is_available():
        raise SystemExit("the demo needs an NVIDIA GPU with CUDA (see SETUP.md)")
    D.gpu_guard()                                       # cap the allocator below the card (Windows spills silently)
    settings = check_settings(args)
    th = settings["decision_thresholds"]
    th_ours, th_orig = (th["ours"]["stop"], th["ours"]["respond"]), (th["original_readout"]["stop"],
                                                                     th["original_readout"]["respond"])
    scenes = load_scenes(args.samples, args.scene)
    print(f"GPU {torch.cuda.get_device_name(0)}; front end: {args.front_end}; thresholds (stop, respond): ours "
          f"{th_ours}, original read-out {th_orig}", flush=True)
    t0 = time.time()
    fe = FrontEnd(args, settings) if args.front_end == "live" else None
    dec = Decider(args)
    torch.cuda.synchronize()
    print(f"models loaded in {time.time() - t0:.0f} s", flush=True)
    print("Each question line: the right answer, then for ours and for the same model's original read-out the "
          "probability of 'stop' (or 'respond') and the decision at the frozen threshold.")

    report, totals, times = [], {"ours": [0, 0], "original": [0, 0]}, []
    for n, scene in enumerate(scenes, 1):
        torch.cuda.synchronize()
        t_scene = time.time()
        rows, inputs, items, kept, same_text = {}, {}, [], 0, 0
        for ver in scene["versions"]:
            row = meta_row(scene, ver)
            rows[ver["version"]] = row
            stored = {p["k"]: stored_front(p) for p in ver["points"]}
            if fe is not None:
                live, kv = fe.run(scene, ver, row, args.samples, stored)
                kept += kv
            for p in ver["points"]:
                k = p["k"]
                tr, tags, snd = live[k][:3] if fe is not None else stored[k]
                text, asks = SIT.build(row, k, tr, tags, snd, "full")
                same_text += text == p["situation_text"]
                if fe is None and (text != p["situation_text"] or asks != p["questions"]):
                    raise SystemExit(f"{p['id']}: rebuilt situation text differs from the stored one")
                qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
                inputs[p["id"]] = {"tr": tr, "tags": tags, "snd": snd, "text": text, "qs": qs,
                                   "scores": live[k][3] if fe is not None else p["front_end"]["speaker_score"]}
                items.append({"id": p["id"], "wave": sf.read(os.path.join(args.samples, p["window"]),
                                                              dtype="float32")[0],
                              "text": text, "marker": "agent" if p["assistant_speaking"] else "user", "qs": qs})
        torch.cuda.synchronize()
        t_front = time.time() - t_scene
        ours, orig = dec.score(items, args.batch)
        d_ours, d_orig = S.decide(ours, *th_ours), S.decide(orig, *th_orig)
        torch.cuda.synchronize()
        t_all = time.time() - t_scene
        times.append(t_all)

        n_pts = sum(len(v["points"]) for v in scene["versions"])
        print(f"\nScene {n}/{len(scenes)}  {scene['scene_id']}  ({scene['part_title']}): {scene['title']}")
        if fe is None:
            print("  front end: stored outputs (as computed when the training set was processed)")
        else:
            how = "whole scene audio" if scene["versions"][0]["audio"] else "8 s windows only"
            if kept:
                how += f"; {kept} earlier speech segment(s) before the window keep their stored transcript and tag"
            print(f"  front end: live ({how}); situation text identical to the stored one at {same_text}/{n_pts} "
                  f"points")
        right = {"ours": [0, 0], "original": [0, 0]}
        for ver in scene["versions"]:
            row = rows[ver["version"]]
            print(f"  version {ver['version']}: {ver['label']}")
            for p in ver["points"]:
                key, x = (scene["scene_id"], ver["version"], p["k"]), inputs[p["id"]]
                print(f"    {p['t']:5.1f} s  {heard_line(row, p['k'], x['tr'], x['tags'], x['snd'])}")
                if args.show_text:
                    print("      " + x["text"].replace("\n", "\n      "))
                rec = {"id": p["id"], "t": p["t"], "situation_text": x["text"], "transcripts": x["tr"],
                       "speaker_tags": x["tags"], "speaker_scores": x["scores"],
                       "detected_sounds": [list(s) for s in x["snd"]], "questions": {}}
                for q in x["qs"]:
                    gold = row["points"][p["k"]]["gold"][q]
                    line = f"      {QNAME[q]:7s}  right: {SAY[gold]:13s}"
                    qrec = {"gold": gold}
                    for name, sc, dd in (("ours", ours, d_ours), ("original", orig, d_orig)):
                        pr, d = sc[key][q], dd[key][q]
                        mark = "" if gold is None else ("ok" if d == gold else "WRONG")
                        if gold is not None:
                            right[name][0] += d == gold
                            right[name][1] += 1
                        line += f" | {name} {pr:.3f} {SAY[d]:13s} {mark:5s}"
                        qrec[name] = {"p": pr, "decision": d}
                    print(line.rstrip())
                    rec["questions"][QNAME[q]] = qrec
                report.append(rec)
        for name in right:
            totals[name][0] += right[name][0]
            totals[name][1] += right[name][1]
        print(f"  right answers: ours {right['ours'][0]}/{right['ours'][1]}, original read-out "
              f"{right['original'][0]}/{right['original'][1]}; time {t_all:.2f} s (front end {t_front:.2f} s, "
              f"decision model {t_all - t_front:.2f} s) for {n_pts} decision point(s)")

    peak = torch.cuda.max_memory_allocated() / 2**30
    print(f"\nAll scenes: ours {totals['ours'][0]}/{totals['ours'][1]} right, original read-out "
          f"{totals['original'][0]}/{totals['original'][1]} right (scored questions only)")
    print(f"time per scene {np.mean(times):.2f} s on average (max {max(times):.2f} s); peak GPU memory "
          f"{peak:.2f} GB allocated, {torch.cuda.max_memory_reserved() / 2**30:.2f} GB reserved")
    if args.out:
        json.dump({"front_end": args.front_end, "thresholds": {"ours": th_ours, "original": th_orig},
                   "points": report, "seconds_per_scene": times, "peak_gpu_gb": peak}, open(args.out, "w"), indent=1)
        print(f"wrote {args.out}")


if __name__ == "__main__":
    main()
